// The HMARK wordmark (1667x617, ratio ~2.702:1), embedded directly as a
// base64 literal rather than read from public/hmark-logo.png at runtime via
// fs.readFileSync. That worked in local dev (the whole repo is on disk) but
// is not safe on Vercel: a dynamically-constructed file path
// (path.join(process.cwd(), "public", ...)) can't be statically traced by
// Next.js's serverless output-file tracing, so the asset can be missing from
// the deployed function bundle even though the local filesystem has it —
// silently throwing ENOENT in production PDF generation.
export const BRAND_LOGO_DATA_URI = "data:image/png;base64,";

export const BRAND_LOGO_RATIO = 1667 / 617;
